var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.path!="Assets/Proto/MountainPass/Scenes/MountainPass.unity")throw new InvalidOperationException("프로토타입 편집 씬 확인 필요");
var mist=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassMountainMist>();var rear=new SerializedObject(mist.RearFog);var renderer=(MeshRenderer)rear.FindProperty("volumeRenderer").objectReferenceValue;var boundary=(Transform)rear.FindProperty("densityBoundary").objectReferenceValue;
