var report=new{scene=scene.path,areaSize=new[]{size.x,size.z},volumeDepth=size.y,top=renderer.bounds.max.y,position=mist.RearFog.transform.position.ToString(),boundary=boundary.position.ToString(),topFade=rear.FindProperty("heightFade").floatValue,edgeFade=rear.FindProperty("edgeFade").floatValue,summitFadeHeight=upper.FindProperty("summitFadeHeight").floatValue,summitClearLeadHeight=upper.FindProperty("summitClearLeadHeight").floatValue,shaderErrors=UnityEditor.ShaderUtil.GetShaderMessages(Shader.Find("Cheon/Prototype/LocalMountainFog")).Count(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error)};
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
